import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { isValidYouTubeUrl, extractVideoId, getThumbnailUrl } from "@/lib/utils";
import { GoogleGenerativeAI } from "@google/generative-ai";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY!);

interface FirecrawlResponse {
  success: boolean;
  markdown?: string;
  metadata?: {
    title?: string;
    description?: string;
    ogTitle?: string;
  };
  error?: string;
}

interface GeminiResult {
  tldr: string;
  translatedSummary: string;
  timestampSummary: Array<{ timestamp: string; summary: string }>;
  actionItems: string[];
}

async function scrapeWithFirecrawl(url: string): Promise<FirecrawlResponse> {
  const res = await fetch("https://api.firecrawl.dev/v1/scrape", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.FIRECRAWL_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ url, formats: ["markdown"] }),
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Firecrawl HTTP ${res.status}: ${err}`);
  }
  return res.json() as Promise<FirecrawlResponse>;
}

async function getYoutubeDuration(url: string): Promise<number | null> {
  try {
    const res = await fetch(url, {
      headers: {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
      },
      next: { revalidate: 3600 } 
    });
    const html = await res.text();

    // Look for approximateDurationMs
    const match = html.match(/"approxDurationMs":"(\d+)"/);
    if (match) return Math.floor(parseInt(match[1]) / 1000);

    // Look for duration string PT...
    const durationMatch = html.match(/"duration":"PT(\d+H)?(\d+M)?(\d+S)?"/);
    if (durationMatch) {
      let totalSeconds = 0;
      if (durationMatch[1]) totalSeconds += parseInt(durationMatch[1]) * 3600;
      if (durationMatch[2]) totalSeconds += parseInt(durationMatch[2]) * 60;
      if (durationMatch[3]) totalSeconds += parseInt(durationMatch[3]);
      return totalSeconds;
    }
    return null;
  } catch (e) {
    console.error("Error fetching duration:", e);
    return null;
  }
}

function formatDuration(seconds: number): string {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return [h, m, s].map(v => v.toString().padStart(2, '0')).join(':');
}

async function analyzeWithGemini(content: string, videoTitle: string, targetLanguage: string, category: string, durationSeconds: number | null): Promise<GeminiResult> {
  const models = ["gemini-1.5-flash", "gemini-2.0-flash", "gemini-flash-latest"];
  const durationText = durationSeconds ? formatDuration(durationSeconds) : "Unknown";
  let lastError: any;

  // Define category-specific instructions
  let categoryInstructions = "";
  if (category === "Lectures & Tutorials") {
    categoryInstructions = `Focus: Structured Learning.
Output Structure for 'tldr' (MUST USE THESE HEADERS):
- TOPIC OVERVIEW
- KEY CONCEPTS
- IMPORTANT DEFINITIONS
- STEP-BY-STEP EXPLANATIONS
- STUDY NOTES
- ACTIONABLE LEARNING POINTS`;
  } else if (category === "News & Interviews") {
    categoryInstructions = `Focus: Key Discussions & Statements.
Output Structure for 'tldr' (MUST USE THESE HEADERS):
- MAIN TOPIC
- KEY STATEMENTS
- IMPORTANT QUOTES
- OPINIONS VS FACTS
- MAJOR TAKEAWAYS`;
  } else if (category === "Business Content") {
    categoryInstructions = `Focus: Strategic Insights & Decisions.
Output Structure for 'tldr' (MUST USE THESE HEADERS):
- BUSINESS PROBLEM
- STRATEGIES DISCUSSED
- MARKET INSIGHTS
- DECISIONS OR RECOMMENDATIONS
- ACTIONABLE BUSINESS LESSONS`;
  } else if (category === "Documentaries") {
    categoryInstructions = `Focus: Analytical Narrative Insights.
Output Structure for 'tldr' (MUST USE THESE HEADERS):
- MAIN THEME
- KEY STORY SEGMENTS
- HISTORICAL / CONTEXTUAL INSIGHTS
- IMPORTANT EVENTS
- FINAL MESSAGE OR CONCLUSION`;
  } else {
    categoryInstructions = `Focus: General Intelligence.
Output Structure for 'tldr': Executive summary of the content.`;
  }

  for (const modelName of models) {
    try {
      console.log(`[AI] Attempting ${modelName} for "${videoTitle}" [Category: ${category}] [Duration: ${durationText}]...`);
      const model = genAI.getGenerativeModel({
        model: modelName,
        generationConfig: { responseMimeType: "application/json" }
      });

      const prompt = `Analyze this YouTube content (${category}) and produce a JSON report.
TITLE: ${videoTitle}
VIDEO DURATION: ${durationText}
CONTENT: ${content}

${categoryInstructions}

Respond ONLY with this JSON schema:
{
  "tldr": "The full specialized analysis according to the structure requested above, in ${targetLanguage}",
  "translatedSummary": "High-quality, professional summary in ${targetLanguage}",
  "timestampSummary": [{ "timestamp": "HH:MM:SS", "summary": "Detailed, specific analysis (3+ sentences) for this segment in ${targetLanguage}" }],
  "actionItems": ["3-5 actionable takeaways/lessons in ${targetLanguage}"]
}

Rules:
1. EVERYTHING must be in ${targetLanguage}.
2. timestampSummary Rules:
   - Generate exactly 6-10 chronological segments.
   - Timestamps MUST fall within the video duration (${durationText}).
   - Distribute timestamps proportionally across the entire timeline (do not group them at the beginning).
   - If the video is long, ensure segments cover the middle and end.
   - The final segment MUST be near the end of the video.
   - Format: "HH:MM:SS" (e.g., "00:05:30").
3. Accuracy and quality are paramount. All text MUST be rewritten in ${targetLanguage}.`;

      const result = await model.generateContent(prompt);
      let text = result.response.text().trim();

      try {
        const parsed = JSON.parse(text) as GeminiResult;
        console.log(`[AI] Success with ${modelName}`);
        return parsed;
      } catch {
        text = text.replace(/^```(?:json)?/i, "").replace(/```$/i, "").trim();
        const parsed = JSON.parse(text) as GeminiResult;
        console.log(`[AI] Success with ${modelName} (after cleanup)`);
        return parsed;
      }
    } catch (err: any) {
      lastError = err;
      const msg = err.message || String(err);
      console.warn(`[AI] Model ${modelName} failed:`, msg);

      if (msg.includes("429") || msg.toLowerCase().includes("quota")) {
        continue;
      }

      // If it's a safety block or other error, let's still try the next model
      continue;
    }
  }

  throw lastError;
}

export async function POST(req: NextRequest) {
  try {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const body = await req.json();
    const { url, targetLanguage = "English", category = "Lectures & Tutorials" } = body;

    if (!url || !isValidYouTubeUrl(url)) {
      return NextResponse.json({ error: "Invalid YouTube URL." }, { status: 400 });
    }

    const videoId = extractVideoId(url);
    const thumbnailUrl = videoId ? getThumbnailUrl(videoId) : null;

    // ΓöÇΓöÇ Step 1: Firecrawl scrape ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    let scrapedContent = "";
    let videoTitle = "YouTube Video";
    let contentSource = `category:${category}`;

    try {
      const scrapeResult = await scrapeWithFirecrawl(url);

      if (scrapeResult.success && scrapeResult.markdown) {
        // Reduced from 12000 to 8000 to optimize token usage on free tier
        scrapedContent = scrapeResult.markdown.slice(0, 8000);
        // Extract title from markdown H1 if present
        const titleMatch = scrapedContent.match(/^#\s+(.+)/m);
        if (titleMatch) videoTitle = titleMatch[1].trim();
        contentSource = "full_page";
      }

      // Fallback to metadata title
      const metaTitle =
        scrapeResult.metadata?.ogTitle ?? scrapeResult.metadata?.title;
      if (metaTitle && videoTitle === "YouTube Video") {
        videoTitle = metaTitle;
      }
    } catch (firecrawlErr) {
      console.error("Firecrawl error:", firecrawlErr);
      // Continue with what we have
    }

    // ΓöÇΓöÇ Step 2: Determine content quality ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const hasContent = scrapedContent.length > 200;

    if (!hasContent) {
      scrapedContent = `[Note: This video appears to be protected or has very limited public text data available. Only the video title "${videoTitle}" is available for analysis.]`;
      contentSource = "title_only";
    }

    // ΓöÇΓöÇ Step 3: Fetch Duration ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const durationSeconds = await getYoutubeDuration(url);

    // ΓöÇΓöÇ Step 4: Gemini analysis ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    let geminiResult: GeminiResult;
    try {
      geminiResult = await analyzeWithGemini(scrapedContent, videoTitle, targetLanguage, category, durationSeconds);
    } catch (aiErr: any) {
      console.error("Gemini error details:", aiErr);

      // Log full error for diagnostics
      try {
        const errorLog = {
          timestamp: new Date().toISOString(),
          error: aiErr instanceof Error ? {
            message: aiErr.message,
            stack: aiErr.stack,
            name: aiErr.name
          } : aiErr,
          videoId: videoId
        };
        // We use a temporary file for server logs if possible, or just console
        console.log("Full AI Error Log:", JSON.stringify(errorLog, null, 2));
      } catch (logErr) {
        console.error("Failed to log error details:", logErr);
      }

      const errorMessage = aiErr instanceof Error ? aiErr.message : String(aiErr);

      // Specifically handle Quota/Rate Limit/429 errors
      if (
        errorMessage.includes("429") || 
        errorMessage.toLowerCase().includes("quota") || 
        errorMessage.toLowerCase().includes("rate limit")
      ) {
        return NextResponse.json(
          { 
            error: "Gemini API Quota Exceeded (Free Tier limit). Please wait 60 seconds before trying again. Google limits the number of requests you can make in a short period.",
            code: "QUOTA_EXCEEDED"
          },
          { status: 429 }
        );
      }

      // Handle safety blocks
      if (errorMessage.toLowerCase().includes("safety") || errorMessage.toLowerCase().includes("finish_reason")) {
        return NextResponse.json(
          { error: "AI analysis was blocked by safety filters. This can happen with certain video topics." },
          { status: 400 }
        );
      }

      return NextResponse.json(
        { error: `AI analysis failed: ${errorMessage.substring(0, 150)}${errorMessage.length > 150 ? '...' : ''}` },
        { status: 500 }
      );
    }

    // ΓöÇΓöÇ Step 5: Save to Supabase ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const { data: summary, error: dbError } = await supabase
      .from("summaries")
      .insert({
        user_id: user.id,
        youtube_url: url,
        video_title: videoTitle,
        thumbnail_url: thumbnailUrl,
        tldr: geminiResult.tldr,
        key_takeaways: geminiResult.timestampSummary,
        sentiment: geminiResult.translatedSummary,
        sentiment_score: 0,
        action_items: geminiResult.actionItems,
        raw_content: scrapedContent.slice(0, 5000),
        content_source: contentSource,
      })
      .select("id")
      .single();

    if (dbError) {
      console.error("DB insert error:", dbError);
      return NextResponse.json(
        { error: "Failed to save summary." },
        { status: 500 }
      );
    }

    return NextResponse.json({ id: summary.id });
  } catch (err) {
    console.error("Summarize API error:", err);
    return NextResponse.json(
      { error: "Unexpected server error." },
      { status: 500 }
    );
  }
}

