"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import toast from "react-hot-toast";
import { isValidYouTubeUrl } from "@/lib/utils";
import { Loader2, Youtube, Sparkles } from "lucide-react";
import Button from "@/components/ui/Button";

export default function UrlForm() {
  const [url, setUrl] = useState("");
  const [targetLanguage, setTargetLanguage] = useState("English");
  const [selectedCategory, setSelectedCategory] = useState("Lectures & Tutorials");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const languages = [
    "English", "Spanish", "French", "German", "Chinese",
    "Japanese", "Hindi", "Arabic", "Portuguese", "Russian"
  ];

  const categories = [
    { id: "lectures", emoji: "≡ƒÄô", title: "Lectures & Tutorials", desc: "Condense educational content into actionable notes." },
    { id: "news", emoji: "≡ƒô░", title: "News & Interviews", desc: "Get the gist of long-form discussions instantly." },
    { id: "business", emoji: "≡ƒÆ╝", title: "Business Content", desc: "Extract decisions from conference talks." },
    { id: "documentary", emoji: "≡ƒÄ¼", title: "Documentaries", desc: "Capture key insights from documentary films." },
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = url.trim();

    if (!trimmed) { toast.error("Please enter a YouTube URL."); return; }
    if (!isValidYouTubeUrl(trimmed)) { toast.error("That doesn't look like a valid YouTube URL."); return; }

    setLoading(true);
    const toastId = toast.loading(`Analyzing ${selectedCategory} in ${targetLanguage}ΓÇª`);

    try {
      const res = await fetch("/api/summarize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: trimmed, targetLanguage, category: selectedCategory }),
      });

      const data = await res.json();

      if (!res.ok) {
        if (res.status === 429) {
          toast.error("Rate limit hit! Please wait 60 seconds before trying another video.", { 
            id: toastId,
            duration: 6000 
          });
        } else {
          toast.error(data.error ?? "Analysis failed.", { id: toastId });
        }
        return;
      }

      toast.success("Intelligence analysis complete!", { id: toastId });
      router.push(`/result/${data.id}`);
      router.refresh();
    } catch (err: any) {
      console.error("UI Submission Error:", err);
      toast.error("Failed to start analysis.", { id: toastId });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full space-y-12">
      <form onSubmit={handleSubmit} className="w-full space-y-4">
        <div className="relative group">
          <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none z-10">
            {loading ? (
              <Loader2 className="w-5 h-5 text-foreground animate-spin" />
            ) : (
              <Youtube className="w-5 h-5 text-muted-foreground group-focus-within:text-foreground transition-colors" />
            )}
          </div>
          <input
            type="url"
            id="youtube-url-input"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            placeholder="Paste YouTube video link here..."
            disabled={loading}
            suppressHydrationWarning
            className="w-full bg-background border border-border rounded-2xl py-6 pl-14 pr-44 text-foreground placeholder-muted-foreground text-[15px] shadow-sm transition-all focus:border-foreground focus:ring-1 focus:ring-foreground/5 disabled:opacity-60 outline-none hover:shadow-md"
          />
          <div className="absolute inset-y-2 right-2 flex items-center gap-2">
            <select
              value={targetLanguage}
              onChange={(e) => setTargetLanguage(e.target.value)}
              disabled={loading}
              suppressHydrationWarning
              className="h-full bg-background border border-border rounded-xl px-4 text-[10px] font-black text-foreground uppercase tracking-widest outline-none focus:border-foreground transition-all cursor-pointer hover:bg-foreground hover:text-background hover:-translate-y-0.5 hover:shadow-lg"
            >
              {languages.map(lang => (
                <option key={lang} value={lang}>{lang}</option>
              ))}
            </select>
            <Button
              type="submit"
              size="sm"
              loading={loading}
              className="h-full px-8 rounded-xl font-black uppercase tracking-[0.2em] text-[10px] hover:bg-foreground hover:text-background hover:-translate-y-0.5 hover:shadow-lg"
            >
              Run
            </Button>
          </div>
        </div>
        <p className="text-[10px] text-muted-foreground mt-4 ml-2 flex items-center gap-2 font-black uppercase tracking-widest">
          <Sparkles className="w-3.5 h-3.5 text-foreground/40" />
          Intelligence Engine Active
        </p>
      </form>

      {/* Category Selection */}
      <div className="grid sm:grid-cols-2 gap-6 animate-fade-in">
        {categories.map((cat) => (
          <button
            key={cat.id}
            type="button"
            onClick={() => setSelectedCategory(cat.title)}
            disabled={loading}
            suppressHydrationWarning
            className={`text-left bg-card border rounded-[2.5rem] p-8 transition-all group flex flex-col items-center sm:items-start relative overflow-hidden ${
              selectedCategory === cat.title
                ? "border-foreground shadow-2xl scale-[1.02] ring-1 ring-foreground"
                : "border-border opacity-50 hover:opacity-100 hover:border-foreground/20 hover:shadow-xl"
            }`}
          >
            {selectedCategory === cat.title && (
              <div className="absolute top-4 right-4 animate-bounce">
                <Sparkles className="w-4 h-4 text-foreground" />
              </div>
            )}
            <div className={`text-4xl mb-6 transition-all transform group-hover:scale-110 ${selectedCategory === cat.title ? "grayscale-0" : "grayscale"}`}>
              {cat.emoji}
            </div>
            <p className="text-xs font-black text-foreground mb-2 uppercase tracking-[0.2em]">{cat.title}</p>
            <p className="text-xs text-muted-foreground leading-relaxed font-medium">{cat.desc}</p>
          </button>
        ))}
      </div>
    </div>
  );
}

