import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import Link from '@tiptap/extension-link';
import { 
    ChevronLeft, 
    Save, 
    Sparkles, 
    Bold, 
    Italic, 
    List, 
    ListOrdered, 
    Code, 
    Heading1, 
    Heading2,
    Share2,
    Download,
    Trash2
} from 'lucide-react';
import React, { useEffect, useState } from 'react';
import { formatDate } from '@/lib/utils';

interface Note {
    id: string;
    user_id: string;
    folder_id: string | null;
    title: string;
    content: Record<string, unknown>; // Content is JSONB from Tiptap
    is_pinned: boolean;
    is_favorite: boolean;
    last_edited_at: string;
    created_at: string;
    updated_at: string;
}

import CharacterCount from '@tiptap/extension-character-count';

interface NoteEditorProps {
    note: Note;
    onSave: (updates: Partial<Note>) => void;
    onBack: () => void;
}

export default function NoteEditor({ note, onSave, onBack }: NoteEditorProps) {
    const [title, setTitle] = useState(note.title);
    const [isSaving, setIsSaving] = useState(false);

    const editor = useEditor({
        extensions: [
            StarterKit,
            Placeholder.configure({
                placeholder: 'Start typing your intelligence notes...',
            }),
            Link.configure({
                openOnClick: false,
            }),
            CharacterCount,
        ],
        content: note.content,
        onUpdate: ({ editor }) => {
            // Debounced auto-save can be added here
        },
    });

    useEffect(() => {
        if (editor && note) {
            editor.commands.setContent(note.content);
            setTitle(note.title);
        }
    }, [note, editor]);

    const handleManualSave = () => {
        setIsSaving(true);
        onSave({
            title,
            content: editor?.getJSON(),
        });
        setTimeout(() => setIsSaving(false), 1000);
    };

    if (!editor) return null;

    return (
        <div className="flex-1 flex flex-col h-full bg-background overflow-hidden animate-fade-in">
            {/* Editor Toolbar */}
            <div className="border-b border-border/50 p-4 flex items-center justify-between bg-card/30 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <button 
                        onClick={onBack}
                        className="p-2 hover:bg-muted rounded-xl transition-all"
                    >
                        <ChevronLeft className="w-5 h-5" />
                    </button>
                    <div className="h-6 w-px bg-border/50 mx-2" />
                    <ToolbarButton 
                        onClick={() => editor.chain().focus().toggleBold().run()} 
                        active={editor.isActive('bold')}
                        icon={Bold} 
                    />
                    <ToolbarButton 
                        onClick={() => editor.chain().focus().toggleItalic().run()} 
                        active={editor.isActive('italic')}
                        icon={Italic} 
                    />
                    <ToolbarButton 
                        onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()} 
                        active={editor.isActive('heading', { level: 1 })}
                        icon={Heading1} 
                    />
                    <ToolbarButton 
                        onClick={() => editor.chain().focus().toggleBulletList().run()} 
                        active={editor.isActive('bulletList')}
                        icon={List} 
                    />
                    <ToolbarButton 
                        onClick={() => editor.chain().focus().toggleCodeBlock().run()} 
                        active={editor.isActive('codeBlock')}
                        icon={Code} 
                    />
                </div>

                <div className="flex items-center gap-3">
                    <button className="flex items-center gap-2 px-4 py-2 bg-foreground/5 text-foreground rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-foreground/10 transition-all">
                        <Sparkles className="w-3.5 h-3.5" />
                        AI Actions
                    </button>
                    <button 
                        onClick={handleManualSave}
                        disabled={isSaving}
                        className="flex items-center gap-2 px-4 py-2 bg-foreground text-background rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-all disabled:opacity-50"
                    >
                        {isSaving ? "Saving..." : <><Save className="w-3.5 h-3.5" /> Save</>}
                    </button>
                </div>
            </div>

            {/* Editor Body */}
            <div className="flex-1 overflow-y-auto p-12 md:p-24 pt-12 md:pt-16 max-w-4xl mx-auto w-full">
                <div className="mb-12">
                     <div className="flex items-center gap-3 mb-6">
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-muted-foreground opacity-40">
                            Last edited {formatDate(note.last_edited_at)}
                        </span>
                    </div>
                    <input 
                        type="text"
                        value={title}
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setTitle(e.target.value)}
                        placeholder="Note Title"
                        className="w-full text-5xl md:text-6xl font-black tracking-tight bg-transparent outline-none placeholder:text-muted-foreground/20 mb-4"
                    />
                </div>

                <div className="prose prose-invert max-w-none prose-p:text-muted-foreground prose-headings:text-foreground prose-strong:text-foreground">
                    <EditorContent editor={editor} className="min-h-[500px] outline-none" />
                </div>
            </div>

            {/* Bottom Status */}
            <div className="p-4 border-t border-border/50 bg-card/10 flex items-center justify-between text-[10px] font-black uppercase tracking-widest text-muted-foreground/40">
                <div className="flex items-center gap-6">
                    <span>Words: {editor.storage.characterCount?.words?.() || 0}</span>
                    <span>Characters: {editor.storage.characterCount?.characters?.() || 0}</span>
                </div>
                <div className="flex items-center gap-4">
                    <button className="hover:text-foreground transition-colors">Export</button>
                    <button className="hover:text-foreground transition-colors">History</button>
                </div>
            </div>
        </div>
    );
}

interface ToolbarButtonProps {
    onClick: () => void;
    active: boolean;
    icon: React.ElementType;
}

function ToolbarButton({ onClick, active, icon: Icon }: ToolbarButtonProps) {
    return (
        <button 
            type="button"
            onClick={onClick}
            className={`p-2 rounded-lg transition-all ${active ? "bg-foreground text-background shadow-lg" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}
        >
            <Icon className="w-4 h-4" />
        </button>
    );
}

"use client";

import React from "react";

import { Pin, Star, Trash2, MoreVertical, Edit3, Copy, Sparkles, StickyNote } from "lucide-react";
import { formatDate } from "@/lib/utils";

interface Note {
    id: string;
    user_id: string;
    folder_id: string | null;
    title: string;
    content: Record<string, unknown>; // Content is JSONB from Tiptap
    is_pinned: boolean;
    is_favorite: boolean;
    last_edited_at: string;
    created_at: string;
    updated_at: string;
}

interface NoteListProps {
    notes: Note[];
    viewMode: "grid" | "list";
    onSelectNote: (id: string) => void;
    onDeleteNote: (id: string) => void;
    onTogglePin: (id: string, pinned: boolean) => void;
    onToggleFavorite: (id: string, fav: boolean) => void;
}

export default function NoteList({ 
    notes, 
    viewMode, 
    onSelectNote, 
    onDeleteNote,
    onTogglePin,
    onToggleFavorite
}: NoteListProps) {
    if (notes.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-16 h-16 rounded-[2rem] bg-foreground/5 border border-border flex items-center justify-center mb-6">
                    <StickyNote className="w-8 h-8 text-foreground/20" />
                </div>
                <h3 className="text-lg font-black uppercase tracking-widest text-foreground/40 mb-2">No notes found</h3>
                <p className="text-muted-foreground text-sm max-w-xs mx-auto">Create your first note to start building your AI knowledge base.</p>
            </div>
        );
    }

    if (viewMode === "list") {
        return (
            <div className="space-y-2">
                {notes.map((note) => (
                    <div 
                        key={note.id}
                        onClick={() => onSelectNote(note.id)}
                        className="group flex items-center gap-4 p-4 bg-card border border-border rounded-xl hover:border-foreground/20 transition-all cursor-pointer"
                    >
                        <div className="flex-1 min-w-0">
                            <h4 className="font-bold text-sm truncate group-hover:text-foreground transition-colors uppercase tracking-wider">{note.title}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <span className="text-[10px] text-muted-foreground/40 font-bold uppercase tracking-tighter">
                                    {formatDate(note.last_edited_at)}
                                </span>
                            </div>
                        </div>
                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                                onClick={(e) => { e.stopPropagation(); onTogglePin(note.id, !note.is_pinned); }}
                                className={`p-2 rounded-lg transition-all ${note.is_pinned ? "text-foreground bg-foreground/5" : "text-muted-foreground hover:bg-muted"}`}
                            >
                                <Pin className="w-3.5 h-3.5" />
                            </button>
                            <button 
                                onClick={(e) => { e.stopPropagation(); onDeleteNote(note.id); }}
                                className="p-2 rounded-lg text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-all"
                            >
                                <Trash2 className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {notes.map((note) => (
                <div 
                    key={note.id} 
                    onClick={() => onSelectNote(note.id)}
                    className="bg-card border border-border rounded-[2.5rem] p-8 hover:border-foreground/20 transition-all cursor-pointer group relative overflow-hidden flex flex-col h-full hover:shadow-2xl hover:-translate-y-1"
                >
                    {/* Active/Status Indicator */}
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${note.is_pinned ? "bg-foreground" : "bg-foreground/5"}`}></div>
                            <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground opacity-60">
                                {note.is_pinned ? "Pinned" : "Note"}
                            </span>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                             <button 
                                onClick={(e) => { e.stopPropagation(); onTogglePin(note.id, !note.is_pinned); }}
                                className={`p-2 rounded-lg transition-all ${note.is_pinned ? "text-foreground bg-foreground/5" : "text-muted-foreground hover:bg-muted"}`}
                            >
                                <Pin className="w-4 h-4" />
                            </button>
                            <button 
                                onClick={(e) => { e.stopPropagation(); onDeleteNote(note.id); }}
                                className="p-2 rounded-lg text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-all"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    </div>

                    <h3 className="font-black text-lg uppercase tracking-tight mb-4 group-hover:text-foreground transition-colors leading-tight truncate">
                        {note.title}
                    </h3>

                    {/* Content Preview - Just a placeholder for now since content is JSONB */}
                    <p className="text-xs text-muted-foreground/60 leading-relaxed font-medium mb-8 line-clamp-3">
                        {typeof note.content === 'string' ? note.content : "Open to view intelligence notes..."}
                    </p>

                    <div className="mt-auto pt-6 border-t border-border/50 flex items-center justify-between">
                        <span className="text-[10px] font-bold text-muted-foreground/40 uppercase tracking-tighter">
                            Updated {formatDate(note.last_edited_at)}
                        </span>
                        <div className="flex items-center gap-2">
                             <button 
                                onClick={(e) => { e.stopPropagation(); onToggleFavorite(note.id, !note.is_favorite); }}
                                className={`transition-all ${note.is_favorite ? "text-foreground" : "text-muted-foreground/20 group-hover:opacity-100"}`}
                            >
                                <Star className={`w-4 h-4 ${note.is_favorite ? "fill-current" : ""}`} />
                            </button>
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
}

